node -e '
const fs=require("fs");const f=process.argv[1];let s=fs.readFileSync(f,"utf8");
const r=[
["native level from native zoom; tile key `(level, tx, ty)`; placement in the smallest containing tile with a coarser bump on overflow; the per-level tile ranges for a view (live band and snapshot band); a sub-pixel culling predicate.","native level from zoom; tile key `(level, tx, ty)`; placement with coarser bump on overflow; per-level view ranges (live and snapshot bands); sub-pixel culling."],
["zod models (stroke with perfect-freehand input points, colour, `nativeZoom`, tile-local bbox, `objectId`); emitted JSON Schema; an Ajv standalone validator; CBOR codec; matching serde structs in `crates/server`.","zod models (stroke points, colour, `nativeZoom`, tile-local bbox, `objectId`), JSON Schema, Ajv standalone validator, CBOR codec, matching serde structs."],
["Preact and wouter shell; a Canvas 2D renderer with continuous zoom and culling below 1 px; one-finger pan, pinch zoom and wheel zoom; freehand markers; primary and secondary colour. Objects are stored per tile in IndexedDB only, with no sync.","Preact and wouter shell; Canvas 2D renderer with continuous zoom and culling below 1 px; pan, pinch and wheel zoom; freehand markers; primary and secondary colour. Objects stored per tile in IndexedDB only."],
["one DO per board with WebSocket hibernation; a hand-rolled frame","one DO per board, hibernating WebSockets; a hand-rolled frame"],
["the Worker checks `Cf-Access-Jwt-Assertion` (signature via WebCrypto, `aud`, `iss`, `exp`) against the team JWKS, cached, before upgrading; it returns 401 otherwise.","before upgrading, the Worker checks `Cf-Access-Jwt-Assertion` (signature, `aud`, `iss`, `exp`) against the cached team JWKS; 401 otherwise."],
];
for(const [a,b] of r){if(!s.includes(a))console.error("MISS",a.slice(0,40));s=s.replace(a,b);}
fs.writeFileSync(f,s);' $f
wc -w $f

